function nextGreaterElements(nums) {
  const n = nums.length;
  const out = new Array(n).fill(-1);
  const stack = []; // indices, not values
  // two passes over the array simulate the wrap-around
  for (let i = 0; i < 2 * n; i++) {
    const val = nums[i % n];
    while (stack.length && nums[stack[stack.length - 1]] < val) out[stack.pop()] = val;
    if (i < n) stack.push(i);
  }
  return out;
}

